    /** SVG height (number for pixels or string for any CSS unit) */
    height?: number | string;
    /** Stroke color - defaults to CSS variable or accent green */
    strokeColor?: string;
    /** Stroke width - defaults to 1 */
    strokeWidth?: number;
    /** Enable drawing animation */
    animate?: boolean;
    /** Add glow effect to stroke */
    glow?: boolean;
    /** Animation duration in seconds (when animate=true) */
    animationDuration?: number;
    /** ViewBox for SVG */
    viewBox?: string;
    /** Callback when animation completes */
