import React, { useEffect, useRef, useState, useCallback } from "react";
import SignSvg from "@/components/signSvg";
import * as styles from "./splashLoader.module.css";

type SplashLoaderProps = {
  onAnimationComplete?: () => void;
};

/**
 * SplashLoader Component - Full-screen loading animation with signature
 * 
 * Features:
 * - Uses CSS Modules with BEM naming
 * - Centers signature using flexbox
 * - Smooth fade-in/scale-in animations
 * - Delegates stroke animation to SignSvg component
 */
const SplashLoader: React.FC<SplashLoaderProps> = ({ onAnimationComplete }) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const hasRunRef = useRef<boolean>(false);
  const onCompleteRef = useRef(onAnimationComplete);
  const [isMounted, setIsMounted] = useState<boolean>(true);
  const [isFadingOut, setIsFadingOut] = useState<boolean>(false);

  // Keep callback ref up to date without triggering effect re-runs
  useEffect(() => {
    onCompleteRef.current = onAnimationComplete;
  }, [onAnimationComplete]);

  // Handle animation completion
  const handleAnimationComplete = useCallback(() => {
    if (!containerRef.current) return;
    
    // Trigger fade-out animation
    setIsFadingOut(true);
    
    // After fade-out completes, unmount component
    const timer = setTimeout(() => {
      setIsMounted(false);
      onCompleteRef.current?.();
    }, 600); // Match CSS animation duration
    
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    // SSR safety check
    if (typeof window === "undefined") return;

    // Prevent multiple runs - animation should only execute once
    if (hasRunRef.current) return;
    hasRunRef.current = true;

    // Fallback: auto-complete after max duration (animation + buffer)
    const maxDuration = 4000; // 2.5s animation + buffer
    const timer = setTimeout(() => {
      handleAnimationComplete();
    }, maxDuration);

    return () => {
      clearTimeout(timer);
    };
  }, [handleAnimationComplete]);

  if (!isMounted) return null;

  // Build container classes with fade-out modifier
  const containerClasses = [
    styles.splashLoader,
    isFadingOut && styles.splashLoader_fadeOut,
  ].filter(Boolean).join(' ');

  return (
    <div
      ref={containerRef}
      className={containerClasses}
      role="progressbar"
      aria-label="Loading portfolio"
    >
      {/* Background glow effect */}
      <div className={styles.splashLoader__glow} />

      {/* Centered signature content */}
      <div className={styles.splashLoader__content}>
        <div className={styles.splashLoader__signature}>
          <SignSvg
            animate={true}
            glow={true}
            strokeColor="var(--color-accent, #14cf45)"
            strokeWidth={1}
            animationDuration={2.5}
            onAnimationComplete={handleAnimationComplete}
            width={320}
            height={286}
          />
        </div>
      </div>
    </div>
  );
};

export default SplashLoader;